  Future<void> create({required String password}) => RustLib.instance.api
      .crateApiSessionVaultSessionCreate(that: this, password: password);

  Future<void> delete({required String id}) => RustLib.instance.api
      .crateApiSessionVaultSessionDelete(that: this, id: id);

  /// Reemplaza los datos de búsqueda. Con `new_password` y `new_notes` en
  /// `None` conserva el secreto, que no sale del núcleo. Con uno solo,
  /// reemplaza esa parte y la otra no sale del núcleo. Con los dos,
  /// reemplaza el secreto completo (repara una entrada dañada). Unas notas
  /// en blanco las quitan.
  Future<void> edit({
    required String id,
    required EntryInput input,
    String? newPassword,
    String? newNotes,
  }) => RustLib.instance.api.crateApiSessionVaultSessionEdit(
    that: this,
    id: id,
    input: input,
    newPassword: newPassword,
    newNotes: newNotes,
  );

  /// Datos de búsqueda y fechas de una entrada, desde la caché del núcleo:
  /// no toca el disco ni el secreto. Un id que no está en la lista da
  /// `EntryNotFound`.
  Future<EntrySummary> entry({required String id}) =>
      RustLib.instance.api.crateApiSessionVaultSessionEntry(that: this, id: id);

  /// Exporta un respaldo a `dest`, que debe ser absoluta y no existir.
  /// Exige la bóveda desbloqueada.
  Future<void> exportBackup({required String dest}) => RustLib.instance.api
      .crateApiSessionVaultSessionExportBackup(that: this, dest: dest);

  /// Entrega la llave de bóveda para la copia del Keystore. Con la bóveda
  /// bloqueada da `Locked`.
  ///
  /// El `Vec` es la copia que sale del núcleo, como al revelar una
  /// contraseña: su borrado es de mejor esfuerzo. En Dart lo pone en ceros
  /// `enableBiometric` después de entregarlo a Kotlin.
  Future<Uint8List> exportVaultKey() => RustLib.instance.api
      .crateApiSessionVaultSessionExportVaultKey(that: this);

  /// Importa el respaldo `backup` sobre la bóveda de la sesión, exista o
  /// no. `password` es la del respaldo.
  ///
  /// Suelta la bóveda actual y llama a `Vault::import`. Si sale bien, la
  /// sesión queda con la importada, desbloqueada. Si falla, vuelve a abrir
  /// la de la ruta: queda bloqueada, o la sesión queda sin bóveda si no se
  /// puede abrir (por ejemplo, en un celular nuevo). En ambos casos
  /// devuelve el error de la importación. El candado se mantiene todo el
  /// ciclo, para que ninguna otra operación se intercale.
  Future<UnlockReport> importBackup({
    required String backup,
    required String password,
  }) => RustLib.instance.api.crateApiSessionVaultSessionImportBackup(
    that: this,
    backup: backup,
    password: password,
  );

  /// `true` también sin bóveda.
  Future<bool> isLocked() =>
      RustLib.instance.api.crateApiSessionVaultSessionIsLocked(that: this);

  /// Bloquea. Sin bóveda, o con la bóveda ya bloqueada, no hace nada.
  ///
  /// Nunca falla: con el `Mutex` envenenado por un pánico anterior,
  /// bloquea igual, porque bloquear solo suelta la llave y es seguro sobre
  /// cualquier estado (#39). El envenenamiento se conserva: el resto de las
  /// operaciones siguen dando `SessionPoisoned`.
  Future<void> lock() =>
      RustLib.instance.api.crateApiSessionVaultSessionLock(that: this);

  /// Abre la bóveda existente; queda bloqueada.
  Future<void> open() =>
      RustLib.instance.api.crateApiSessionVaultSessionOpen(that: this);

  /// Notas de una entrada, para mostrarlas. La contraseña se descarta sin
  /// salir del núcleo.
  Future<String?> revealNotes({required String id}) => RustLib.instance.api
      .crateApiSessionVaultSessionRevealNotes(that: this, id: id);

  /// Contraseña de una entrada, para mostrarla o copiarla. Las notas se
  /// descartan sin salir del núcleo.
  Future<String> revealPassword({required String id}) => RustLib.instance.api
      .crateApiSessionVaultSessionRevealPassword(that: this, id: id);

  /// Entradas que coinciden con `query`, la mejor primero. Sin texto,
  /// todas: las usadas más recientemente primero.
  Future<List<EntrySummary>> search({required String query}) => RustLib
      .instance
      .api
      .crateApiSessionVaultSessionSearch(that: this, query: query);

  Future<UnlockReport> unlock({required String password}) => RustLib
      .instance
      .api
      .crateApiSessionVaultSessionUnlock(that: this, password: password);

  /// Desbloquea con la llave que liberó el Keystore.
  ///
  /// La llave recibida se pone en ceros al soltarse, en todos los caminos.
  /// Un largo distinto de 32 da `WrongVaultKey` sin tocar la bóveda, así
  /// que con la bóveda ya desbloqueada da `WrongVaultKey` y no
  /// `AlreadyUnlocked`; en la práctica no ocurre, porque la pantalla de
  /// desbloqueo solo existe con la bóveda bloqueada.
  Future<UnlockReport> unlockWithKey({required List<int> key}) => RustLib
      .instance
      .api
      .crateApiSessionVaultSessionUnlockWithKey(that: this, key: key);
}
